"use client";

import {
  forwardRef,
  useCallback,
  useEffect,
  useRef,
  useState,
  type FocusEvent,
  type HTMLAttributes,
  type KeyboardEvent,
  type MouseEvent,
  type PointerEvent,
} from "react";
import { animate, motion, useMotionValue, useMotionValueEvent, useReducedMotion, useTransform } from "framer-motion";
import { cn } from "@/lib/utils";
import { fit, shortAgo } from "./charset";
import { FlapBoard, type FlapRowLink } from "./FlapBoard";
import { MAX_HISTORY, type Commit } from "./types";

// Your latest commit on a split-flap board. Hover (or focus, or tap) and the rows below it turn
// over to the commits before; leave and they turn back to blank. The flaps only ever turn forward,
// like the real thing, so a hover that changes its mind mid-turn just carries on to the new word.
//
// Commits come in as data; SplitFlapBoardLive polls an endpoint for them. The board arrives blank
// and flips your latest in, so the first thing anyone sees is the board doing what it does.

const AGE = 3;
const MESSAGE = 20;
const COLUMNS = AGE + MESSAGE;
const BLANK = " ".repeat(COLUMNS);
const MINUTE = 60_000;

const isoDay = (date: Commit["date"]) => {
  const t = date == null ? NaN : new Date(date).getTime();
  return Number.isFinite(t) ? new Date(t).toISOString().slice(0, 10) : null;
};

const DEFAULT_LABELS = { latest: "Latest commit", recent: "Recent commits", empty: "Nothing pushed yet" };

// Kept in a .tsx file on purpose: the docs Tailwind pass only scans .tsx for class names.
const EYEBROW = "text-[clamp(11px,2.3cqw,13px)] font-medium uppercase leading-none tracking-[0.08em] text-[#888]";
const META = "text-[clamp(9.5px,1.95cqw,11px)] font-semibold uppercase leading-none tracking-[0.12em]";

const GITHUB_PATH =
  "M12 .297c-6.63 0-12 5.373-12 12 0 5.303 3.438 9.8 8.205 11.385.6.113.82-.258.82-.577 0-.285-.01-1.04-.015-2.04-3.338.724-4.042-1.61-4.042-1.61C4.422 18.07 3.633 17.7 3.633 17.7c-1.087-.744.084-.729.084-.729 1.205.084 1.838 1.236 1.838 1.236 1.07 1.835 2.809 1.305 3.495.998.108-.776.417-1.305.76-1.605-2.665-.3-5.466-1.332-5.466-5.93 0-1.31.465-2.38 1.235-3.22-.135-.303-.54-1.523.105-3.176 0 0 1.005-.322 3.3 1.23.96-.267 1.98-.399 3-.405 1.02.006 2.04.138 3 .405 2.28-1.552 3.285-1.23 3.285-1.23.645 1.653.24 2.873.12 3.176.765.84 1.23 1.91 1.23 3.22 0 4.61-2.805 5.625-5.475 5.92.42.36.81 1.096.81 2.22 0 1.606-.015 2.896-.015 3.286 0 .315.21.69.825.57C20.565 22.092 24 17.592 24 12.297c0-6.627-5.373-12-12-12";

export interface SplitFlapBoardProps extends Omit<HTMLAttributes<HTMLElement>, "children"> {
  /** Commits, newest first. The first sits on the top row; the next `history` turn in on hover. */
  commits: Commit[];
  /** GitHub username in the footer. Shown uppercase. */
  user?: string;
  /** How many earlier commits the hover reveals, 0–4. */
  history?: number;
  /** Override any of the card's words, for localisation. */
  labels?: Partial<typeof DEFAULT_LABELS>;
  /** Force the hover state open or closed. Leave undefined for normal hover/focus/tap behaviour. */
  open?: boolean;
  /** Still waiting for data: the board stays blank instead of saying there's nothing. */
  pending?: boolean;
}

export const SplitFlapBoard = forwardRef<HTMLElement, SplitFlapBoardProps>(function SplitFlapBoard(
  {
    commits,
    user,
    history = 3,
    labels,
    open: forced,
    pending = false,
    className,
    style,
    onPointerEnter,
    onPointerLeave,
    onPointerDown,
    onFocus,
    onBlur,
    onKeyDown,
    onClickCapture,
    ...rest
  },
  ref
) {
  const still = useReducedMotion() ?? false;
  const words = { ...DEFAULT_LABELS, ...labels };
  const rows = 1 + Math.max(0, Math.min(MAX_HISTORY, Math.floor(history)));
  const [current, ...older] = commits;
  const earlier = older.slice(0, rows - 1);
  const hasHistory = earlier.length > 0;

  // Ages tick over on their own, so a card left open still reads true. The clock starts after
  // mount, so server and client render the same blank board and the flaps turn in from there.
  const [now, setNow] = useState(0);
  useEffect(() => {
    setNow(Date.now());
    const id = setInterval(() => setNow(Date.now()), MINUTE);
    return () => clearInterval(id);
  }, []);
  const fresh = now > 0 && !!current?.date && now - new Date(current.date).getTime() < 60 * MINUTE;

  // ── Open state: mouse hover, keyboard focus, or a tap on touch screens. Escape dismisses. ──
  const root = useRef<HTMLElement | null>(null);
  const setRoot = useCallback(
    (node: HTMLElement | null) => {
      root.current = node;
      if (typeof ref === "function") ref(node);
      else if (ref) ref.current = node;
    },
    [ref]
  );
  const [hover, setHover] = useState(false);
  const [focus, setFocus] = useState(false);
  const [tapped, setTapped] = useState(false);
  const [dismissed, setDismissed] = useState(false);
  const isOpen = (forced ?? (!dismissed && (hover || focus || tapped))) && hasHistory;
  const lastPointer = useRef<string>("mouse");
  const inHistory = (node: EventTarget | null) => node instanceof Element && !!node.closest("[data-sf-history]");

  useEffect(() => {
    if (!tapped) return;
    const close = (e: globalThis.PointerEvent) => {
      if (!root.current?.contains(e.target as Node)) setTapped(false);
    };
    document.addEventListener("pointerdown", close);
    return () => document.removeEventListener("pointerdown", close);
  }, [tapped]);

  // The flaps are their own physics; this only crossfades the words around them.
  const open = useMotionValue(isOpen ? 1 : 0);
  useEffect(() => {
    const controls = animate(open, isOpen ? 1 : 0, still ? { duration: 0.15, ease: "linear" } : { type: "spring", stiffness: 170, damping: 26 });
    return () => controls.stop();
  }, [isOpen, still, open]);
  const [interactive, setInteractive] = useState(isOpen);
  useMotionValueEvent(open, "change", (v) => setInteractive(v > 0.5));
  const latestOpacity = useTransform(open, [0, 0.5], [1, 0]);
  const recentOpacity = useTransform(open, [0.5, 1], [0, 1]);

  const handlers = {
    onPointerEnter(e: PointerEvent<HTMLElement>) {
      onPointerEnter?.(e);
      if (e.pointerType !== "mouse") return;
      setHover(true);
      setDismissed(false);
    },
    onPointerLeave(e: PointerEvent<HTMLElement>) {
      onPointerLeave?.(e);
      if (e.pointerType === "mouse") setHover(false);
    },
    onPointerDown(e: PointerEvent<HTMLElement>) {
      onPointerDown?.(e);
      lastPointer.current = e.pointerType;
    },
    onClickCapture(e: MouseEvent<HTMLElement>) {
      onClickCapture?.(e);
      // On touch, the first tap opens the board instead of following a link. Keyboard clicks
      // (detail 0) always go through.
      if (lastPointer.current === "mouse" || e.detail === 0 || forced !== undefined || isOpen || !hasHistory) return;
      e.preventDefault();
      setTapped(true);
      setDismissed(false);
    },
    onFocus(e: FocusEvent<HTMLElement>) {
      onFocus?.(e);
      // Keyboard focus on an earlier commit's row opens the board; back on the top row, it closes.
      if (!(e.target as HTMLElement).matches?.(":focus-visible")) return;
      const toHistory = inHistory(e.target);
      setFocus(toHistory);
      if (toHistory) setDismissed(false);
    },
    onBlur(e: FocusEvent<HTMLElement>) {
      onBlur?.(e);
      if (!inHistory(e.relatedTarget)) setFocus(false);
    },
    onKeyDown(e: KeyboardEvent<HTMLElement>) {
      onKeyDown?.(e);
      if (e.key !== "Escape" || !isOpen) return;
      e.stopPropagation();
      if (inHistory(document.activeElement)) {
        const first = root.current?.querySelector<HTMLElement>("a[aria-label]:not([data-sf-history])");
        (first ?? root.current)?.focus();
      }
      setDismissed(true);
      setTapped(false);
    },
  };

  const line = (c: Commit) => shortAgo(c.date, now) + fit(c.message.split("\n")[0], MESSAGE);
  const lines = Array.from({ length: rows }, (_, r) => {
    if (r === 0) return pending || !now ? BLANK : current ? line(current) : " ".repeat(AGE) + fit(words.empty, MESSAGE);
    const c = earlier[r - 1];
    return isOpen && c ? line(c) : BLANK;
  });
  const link = (c: Commit | undefined): FlapRowLink | null =>
    c?.url ? { href: c.url, label: [c.message.split("\n")[0], c.repo, isoDay(c.date)].filter(Boolean).join(" · ") } : null;
  const links = [link(current), ...Array.from({ length: rows - 1 }, (_, i) => link(earlier[i]))];

  const repoUrl = current?.url?.split("/commit/")[0];
  const sha = current?.sha?.slice(0, 7);
  const label = pending ? words.latest : current ? `${words.latest}: ${current.message.split("\n")[0]}${current.repo ? ` in ${current.repo}` : ""}` : words.empty;

  return (
    <article
      ref={setRoot}
      tabIndex={-1}
      aria-label={label}
      className={cn(
        "relative isolate w-full max-w-[560px] select-none overflow-hidden rounded-[28px] text-left outline-none [container-type:inline-size]",
        className
      )}
      style={{
        aspectRatio: "560 / 292",
        background:
          "repeating-linear-gradient(135deg, rgba(255,255,255,0.013) 0 1px, transparent 1px 4px), linear-gradient(180deg, #181818, #121212)",
        boxShadow:
          "inset 0 0 0 1px rgba(255,255,255,0.06), inset 0 1px 0 rgba(255,255,255,0.07), 0 24px 48px -24px rgba(0,0,0,0.85)",
        ...style,
      }}
      {...rest}
      {...handlers}
    >
      <div className="absolute inset-[clamp(18px,5cqw,28px)] flex flex-col justify-between">
        <header className="flex items-center justify-between gap-4">
          <div className="flex min-w-0 items-center gap-[clamp(6px,1.45cqw,8px)]">
            <svg
              viewBox="0 0 24 24"
              aria-hidden
              className="size-[clamp(13px,2.7cqw,15px)] shrink-0 transition-[color,filter] duration-700 ease-out"
              style={{ color: fresh ? "#e5e5e5" : "#5f5f5f", filter: fresh ? "drop-shadow(0 0 5px rgba(255,255,255,0.35))" : "none" }}
            >
              <path fill="currentColor" d={GITHUB_PATH} />
            </svg>
            <span className="relative">
              <motion.span style={{ opacity: latestOpacity }} className={cn(EYEBROW, "block")}>
                {words.latest}
              </motion.span>
              <motion.span aria-hidden style={{ opacity: recentOpacity }} className={cn(EYEBROW, "absolute left-0 top-0 whitespace-nowrap")}>
                {words.recent}
              </motion.span>
            </span>
          </div>
          {current?.repo &&
            (repoUrl ? (
              <a
                href={repoUrl}
                target="_blank"
                rel="noopener noreferrer"
                className="min-w-0 truncate rounded-[4px] text-[clamp(11px,2.3cqw,13px)] font-medium leading-none text-[#aaa] outline-none transition-colors duration-150 hover:text-white focus-visible:outline-2 focus-visible:outline-solid focus-visible:outline-offset-2 focus-visible:outline-white/35"
              >
                {current.repo}
              </a>
            ) : (
              <span className="min-w-0 truncate text-[clamp(11px,2.3cqw,13px)] font-medium leading-none text-[#aaa]">{current.repo}</span>
            ))}
        </header>

        <FlapBoard key={rows} lines={lines} columns={COLUMNS} accent={AGE} links={links} interactive={interactive} still={still} />

        <footer className="flex items-center justify-between gap-4">
          <span className={cn(META, "min-w-0 truncate text-[#aaa]")}>{user ?? ""}</span>
          {sha && <span className={cn(META, "shrink-0 font-mono tracking-[0.06em] text-[#5f5f5f]")}>{sha}</span>}
        </footer>
      </div>
    </article>
  );
});

export default SplitFlapBoard;

"use client";

import { useEffect, useRef, type CSSProperties } from "react";
import { CHARSET, charIndex } from "./charset";
import { createFlap, FlapEvent, stepFlap, type Flap } from "./flap";

// The board: rows of flap cells and the engine that turns them.
//
// Every cell is four faces: the static top and bottom halves, and the flap itself, whose front is
// the top half of the character falling away and whose back is the bottom half of the next one.
// The engine runs one rAF loop for the whole board, only while some flap is moving, and writes
// transforms and characters straight to the DOM. React renders the cells once and never again,
// however many flaps turn.
//
// Light comes from above: the falling flap darkens as it tips toward you, its back catches the
// light as it passes horizontal, and it throws a shadow on the half below it as it comes down.

const SIZE = CHARSET.length;

/** Ripple: each cell starts a little after the one to its left, and each row after the one above. */
const COLUMN_DELAY = 0.016;
const ROW_DELAY = 0.06;
const JITTER_DELAY = 0.03;

/** Repeatable 0–1 noise per cell, so the board settles the same way on every visit. */
const noise = (i: number) => {
  const x = Math.sin(i * 12.9898 + 78.233) * 43758.5453;
  return x - Math.floor(x);
};

// Kept in a .tsx file on purpose: the docs Tailwind pass only scans .tsx for class names.
const HALF = "pointer-events-none absolute inset-x-0 h-[calc(50%-0.5px)] overflow-hidden";
const TOP = `${HALF} top-0 rounded-t-[0.5cqw] bg-[linear-gradient(180deg,#2b2b2b,#232323)] shadow-[inset_0_1px_0_rgba(255,255,255,0.075)]`;
// The lip of the flap above shades the first third of every lower half.
const BOTTOM = `${HALF} bottom-0 rounded-b-[0.5cqw] bg-[linear-gradient(180deg,rgba(0,0,0,0.42),rgba(0,0,0,0)_38%),linear-gradient(180deg,#1f1f1f,#1a1a1a)]`;
const GLYPH = "absolute inset-x-0 flex h-[200%] items-center justify-center leading-none";
const OVERLAY = "absolute inset-0 opacity-0";
const HIDDEN_BACK: CSSProperties = { backfaceVisibility: "hidden", WebkitBackfaceVisibility: "hidden" };

export interface FlapRowLink {
  href: string;
  label: string;
}

export interface FlapBoardProps {
  /** One string per row, each `columns` characters long. Changing a character turns that cell to it. */
  lines: string[];
  columns: number;
  /** Leading columns drawn in the accent colour, with a gap after them (the age column). */
  accent?: number;
  /** A link per row, laid over it; rows with history: true open the card when focused. */
  links?: (FlapRowLink | null)[];
  /** Index of the first row that counts as history (for focus handling in the card). */
  historyFrom?: number;
  /** Rows from `historyFrom` on take pointer clicks only while true. */
  interactive?: boolean;
  /** Reduced motion: characters change in place. */
  still?: boolean;
}

interface Faces {
  topText: HTMLElement;
  bottomText: HTMLElement;
  back: HTMLElement;
  backText: HTMLElement;
  glint: HTMLElement;
  front: HTMLElement;
  frontText: HTMLElement;
  shade: HTMLElement;
  cast: HTMLElement;
}

export function FlapBoard({ lines, columns, accent = 0, links, historyFrom = 1, interactive = true, still = false }: FlapBoardProps) {
  const board = useRef<HTMLDivElement | null>(null);
  const engine = useRef<ReturnType<typeof createEngine> | null>(null);
  const rows = lines.length;

  useEffect(() => {
    const root = board.current;
    if (!root) return;
    const faces = [...root.querySelectorAll<HTMLElement>("[data-flap]")].map(readFaces);
    engine.current = createEngine(faces, columns);
    return () => {
      engine.current?.destroy();
      engine.current = null;
    };
  }, [rows, columns]);

  const text = lines.join("\n");
  useEffect(() => {
    engine.current?.set(text.split("\n"), still);
  }, [text, still, rows, columns]);

  const template = accent > 0 ? `repeat(${accent}, 1fr) 0.5fr repeat(${columns - accent}, 1fr)` : `repeat(${columns}, 1fr)`;

  return (
    <div className="relative rounded-[2.6cqw] bg-[#0b0b0b] p-[2.1cqw] shadow-[inset_0_0.4cqw_1cqw_rgba(0,0,0,0.85),inset_0_0_0_1px_rgba(0,0,0,0.7),0_1px_0_rgba(255,255,255,0.06)]">
      <div ref={board} aria-hidden className="flex flex-col gap-y-[1.05cqw]">
        {Array.from({ length: rows }, (_, r) => (
          <div key={r} className="grid gap-x-[0.42cqw]" style={{ gridTemplateColumns: template }}>
            {Array.from({ length: columns }, (_, c) => (
              <Cell key={c} accent={c < accent} style={accent > 0 && c === accent ? { gridColumnStart: accent + 2 } : undefined} />
            ))}
          </div>
        ))}
      </div>

      {/* Links sit over their rows, outside the aria-hidden flaps. */}
      {links && (
        <div className="pointer-events-none absolute inset-[2.1cqw] flex flex-col gap-y-[1.05cqw]">
          {Array.from({ length: rows }, (_, r) => {
            const link = links[r];
            const history = r >= historyFrom;
            return (
              <div key={r} className="relative flex-1">
                {link && (
                  <a
                    href={link.href}
                    target="_blank"
                    rel="noopener noreferrer"
                    aria-label={link.label}
                    data-sf-history={history ? "" : undefined}
                    className="absolute -inset-[0.5cqw] rounded-[0.9cqw] outline-none transition-colors duration-150 hover:bg-white/[0.025] focus-visible:outline-2 focus-visible:outline-solid focus-visible:outline-offset-1 focus-visible:outline-white/35"
                    style={{ pointerEvents: !history || interactive ? "auto" : "none" }}
                  />
                )}
              </div>
            );
          })}
        </div>
      )}

      {/* Light from above, over the whole face of the board. */}
      <div className="pointer-events-none absolute inset-0 rounded-[2.6cqw] bg-[linear-gradient(180deg,rgba(255,255,255,0.035),rgba(255,255,255,0)_45%)]" />
    </div>
  );
}

function Cell({ accent, style }: { accent: boolean; style?: CSSProperties }) {
  return (
    <span
      data-flap
      className="relative block aspect-[7/10] rounded-[0.5cqw] bg-[#070707] text-[2.95cqw] font-semibold shadow-[0_0.3cqw_0.6cqw_rgba(0,0,0,0.6)] [perspective:32cqw]"
      style={{ color: accent ? "#efb54a" : "#ece8de", ...style }}
    >
      <span className={TOP}>
        <span className={`${GLYPH} top-0`} />
      </span>
      <span className={BOTTOM}>
        <span className={`${GLYPH} bottom-0`} />
        <span className={`${OVERLAY} bg-[linear-gradient(180deg,rgba(0,0,0,0.9),rgba(0,0,0,0.3))]`} />
      </span>
      <span className={`${BOTTOM} origin-top`} style={{ ...HIDDEN_BACK, transform: "rotateX(0deg)" }}>
        <span className={`${GLYPH} bottom-0`} />
        <span className={`${OVERLAY} bg-white`} />
      </span>
      <span className={`${TOP} origin-bottom`} style={HIDDEN_BACK}>
        <span className={`${GLYPH} top-0`} />
        <span className={`${OVERLAY} bg-black`} />
      </span>
      {/* Hinge pins, either side of the split. */}
      <span className="pointer-events-none absolute left-0 top-1/2 h-[14%] w-[8%] -translate-y-1/2 rounded-r-[1px] bg-[#0c0c0c] shadow-[inset_0_1px_0_rgba(255,255,255,0.08)]" />
      <span className="pointer-events-none absolute right-0 top-1/2 h-[14%] w-[8%] -translate-y-1/2 rounded-l-[1px] bg-[#0c0c0c] shadow-[inset_0_1px_0_rgba(255,255,255,0.08)]" />
    </span>
  );
}

function readFaces(cell: HTMLElement): Faces {
  const [top, bottom, back, front] = [...cell.children] as HTMLElement[];
  return {
    topText: top.children[0] as HTMLElement,
    bottomText: bottom.children[0] as HTMLElement,
    cast: bottom.children[1] as HTMLElement,
    back,
    backText: back.children[0] as HTMLElement,
    glint: back.children[1] as HTMLElement,
    front,
    frontText: front.children[0] as HTMLElement,
    shade: front.children[1] as HTMLElement,
  };
}

function createEngine(faces: Faces[], columns: number) {
  const flaps: Flap[] = faces.map((_, i) => createFlap(0, 0.93 + 0.14 * noise(i)));
  let raf = 0;
  let last = 0;

  const glyph = (i: number) => CHARSET[i] === " " ? "" : CHARSET[i];
  const write = (el: HTMLElement, i: number) => {
    const ch = glyph(i);
    if (el.textContent !== ch) el.textContent = ch;
  };

  // A flap was released: the falling front still shows the old top half; the half it uncovers and
  // the back that will land both show the next character.
  const release = (cell: Faces, cur: number) => {
    const next = (cur + 1) % SIZE;
    write(cell.topText, next);
    write(cell.backText, next);
    write(cell.frontText, cur);
    write(cell.bottomText, cur);
  };
  // Landed for good: every face agrees, so the rebound shows the same character underneath.
  const rest = (cell: Faces, cur: number) => {
    write(cell.bottomText, cur);
    write(cell.frontText, cur);
  };

  const paint = (cell: Faces, f: Flap) => {
    const falling = f.phase === "flip";
    const rad = (f.theta * Math.PI) / 180;
    cell.front.style.transform = `rotateX(${falling ? -f.theta : 0}deg)`;
    cell.back.style.transform = `rotateX(${180 - f.theta}deg)`;
    cell.shade.style.opacity = falling && f.theta < 90 ? ((f.theta / 90) * 0.6).toFixed(3) : "0";
    cell.glint.style.opacity = f.theta > 90 && f.phase !== "idle" ? (Math.sin(rad) * 0.16).toFixed(3) : "0";
    cell.cast.style.opacity = f.phase !== "idle" ? (Math.sin(rad) * 0.55).toFixed(3) : "0";
  };

  const tick = (now: number) => {
    const dt = last ? Math.min(1 / 30, (now - last) / 1000) : 1 / 60;
    last = now;
    let moving = false;
    for (let i = 0; i < flaps.length; i++) {
      const f = flaps[i];
      if (f.phase === "idle" && f.cur === f.target) continue;
      moving = true;
      const event = stepFlap(f, dt, SIZE);
      if (event === FlapEvent.Start || event === FlapEvent.LandStart) release(faces[i], f.cur);
      else if (event === FlapEvent.Land) rest(faces[i], f.cur);
      paint(faces[i], f);
    }
    if (moving) raf = requestAnimationFrame(tick);
    else {
      raf = 0;
      last = 0;
    }
  };

  return {
    set(lines: string[], still: boolean) {
      flaps.forEach((f, i) => {
        const r = Math.floor(i / columns);
        const c = i % columns;
        const target = charIndex(lines[r]?.[c] ?? " ");
        if (still) {
          Object.assign(f, { cur: target, target, theta: 180, omega: 0, phase: "idle", delay: 0 });
          const cell = faces[i];
          [cell.topText, cell.bottomText, cell.backText, cell.frontText].forEach((el) => write(el, target));
          paint(cell, f);
          return;
        }
        if (f.target === target) return;
        f.target = target;
        // A flap already turning just carries on to the new character; a resting one joins the ripple.
        if (f.phase === "idle") f.delay = c * COLUMN_DELAY + r * ROW_DELAY + noise(i + 101) * JITTER_DELAY;
      });
      if (!still && !raf) raf = requestAnimationFrame(tick);
    },
    destroy() {
      cancelAnimationFrame(raf);
      raf = 0;
    },
  };
}

// One flap cell's mechanics, in degrees and seconds. Pure, so it can be stepped and reasoned about
// without a DOM.
//
// θ is how far the current flap has fallen: 0 standing up, 180 lying on the one below. A motor
// releases each flap with a small push and gravity does the rest, so it starts slow and slaps
// down fast. While the drum still has characters to turn through, the next flap is released the
// moment one lands. On the last one, the flap bounces off the stop and rings down to rest.

/** Seconds per flap at nominal speed. */
export const FLIP_TIME = 0.042;
/** Share of the 180° the motor's push covers; the rest is gravity. */
const PUSH_SHARE = 0.55;
const OMEGA0 = (180 / FLIP_TIME) * PUSH_SHARE;
const GRAVITY = (2 * 180 * (1 - PUSH_SHARE)) / FLIP_TIME ** 2;
/** How much speed a landing flap keeps as it bounces off the stop. */
const RESTITUTION = 0.32;
/** Below this rebound speed (°/s) the flap just stays down. */
const SETTLE_OMEGA = 320;

export type Phase = "idle" | "flip" | "bounce";

export interface Flap {
  /** Character index showing (or, mid-flip, the one falling away). */
  cur: number;
  target: number;
  theta: number;
  omega: number;
  phase: Phase;
  /** Seconds to wait before starting; gives the ripple across the board. */
  delay: number;
  /** Speed multiplier for this cell's mechanism, near 1, so cells drift apart a little. */
  rate: number;
}

/** What happened this step, so the renderer knows which faces need new characters. */
export const FlapEvent = {
  None: 0,
  /** A flap was released: cur → cur + 1 is now in motion. */
  Start: 1,
  /** A flap landed and the cell rests on `cur`. */
  Land: 2,
  /** A flap landed and the next was released straight away. */
  LandStart: 3,
} as const;
export type FlapEvent = (typeof FlapEvent)[keyof typeof FlapEvent];

export const createFlap = (cur: number, rate = 1): Flap => ({ cur, target: cur, theta: 180, omega: 0, phase: "idle", delay: 0, rate });

export function stepFlap(f: Flap, dt: number, size: number): FlapEvent {
  const g = GRAVITY * f.rate * f.rate;

  if (f.phase === "idle") {
    if (f.cur === f.target) return FlapEvent.None;
    if (f.delay > 0) {
      f.delay -= dt;
      if (f.delay > 0) return FlapEvent.None;
    }
    f.phase = "flip";
    f.theta = 0;
    f.omega = OMEGA0 * f.rate;
    return FlapEvent.Start;
  }

  f.omega += g * dt;
  f.theta += f.omega * dt;
  if (f.theta < 180) return FlapEvent.None;

  if (f.phase === "flip") {
    f.cur = (f.cur + 1) % size;
    if (f.cur !== f.target) {
      f.theta = 0;
      f.omega = OMEGA0 * f.rate;
      return FlapEvent.LandStart;
    }
    f.theta = 180;
    f.omega = -f.omega * RESTITUTION;
    f.phase = "bounce";
    return FlapEvent.Land;
  }

  // Bouncing: back on the stop.
  f.theta = 180;
  const rebound = Math.abs(f.omega) * RESTITUTION;
  if (rebound < SETTLE_OMEGA) {
    f.omega = 0;
    f.phase = "idle";
  } else f.omega = -rebound;
  return FlapEvent.None;
}

// What the flaps can show, in the order they turn past. A real board's drum only goes forward, so
// getting from one character to another means turning through everything in between; the order
// puts blank first, then the letters, so most words arrive quickly from a cleared board.
export const CHARSET = " ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789.,-:/'!?&#+()";

const INDEX = new Map([...CHARSET].map((ch, i) => [ch, i]));

/** Position of a character on the drum; anything the drum doesn't carry becomes blank. */
export const charIndex = (ch: string) => INDEX.get(ch) ?? 0;

/** Upper-cased, accents dropped, unknown characters blanked, whitespace collapsed. */
export function normalize(text: string) {
  return text
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .toUpperCase()
    .replace(/[‘’`]/g, "'")
    .replace(/[“”"]/g, "'")
    .replace(/[–—_]/g, "-")
    .split("")
    .map((ch) => (INDEX.has(ch) ? ch : " "))
    .join("")
    .replace(/\s+/g, " ")
    .trim();
}

/**
 * Fits text to `width` cells: padded with blanks, or cut at the last word that fits. A long first
 * word is cut mid-word rather than leaving the row nearly empty.
 */
export function fit(text: string, width: number) {
  const clean = normalize(text);
  if (clean.length <= width) return clean.padEnd(width, " ");
  const space = clean.lastIndexOf(" ", width);
  const cut = space >= width * 0.55 ? clean.slice(0, space) : clean.slice(0, width);
  // A cut line shouldn't end on a dangling comma or dash.
  return cut.replace(/[\s.,\-:/&+(]+$/, "").padEnd(width, " ");
}

const MINUTE = 60_000;

/** Three-cell age, right-aligned like a departure time: "NOW", " 5M", "12H", " 3D", " 6W", " 2Y". */
export function shortAgo(date: string | number | Date | null | undefined, now = Date.now()) {
  if (date == null) return "   ";
  const t = new Date(date).getTime();
  if (!Number.isFinite(t)) return "   ";
  const m = Math.max(0, Math.floor((now - t) / MINUTE));
  const label =
    m < 1 ? "NOW" : m < 60 ? `${m}M` : m < 1440 ? `${Math.floor(m / 60)}H` : m < 14 * 1440 ? `${Math.floor(m / 1440)}D` : m < 365 * 1440 ? `${Math.floor(m / 10080)}W` : `${Math.min(99, Math.floor(m / 525_600))}Y`;
  return label.padStart(3, " ");
}

export interface Commit {
  /** The commit message. Only its first line is shown. */
  message: string;
  /** Repository name, e.g. "adgrid-ui". */
  repo?: string;
  /** Full or short SHA; the footer shows the first 7 characters. */
  sha?: string;
  /** Link to the commit. */
  url?: string;
  /** When it was authored: ISO string, epoch ms or Date. */
  date?: string | number | Date | null;
}

/** Earlier commits the hover can reveal, under the latest. */
export const MAX_HISTORY = 4;

